import { styled, View } from '@tamagui/web';
import type { ReactNode } from 'react';

import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';
import { prependClassName } from '../../helpers/prependClassName';
import type { ElementPressHandlers, NavAttributes } from '../../types/ElementAttributes';

export type NavBarProps = NavAttributes &
	ElementPressHandlers & {
		children?: ReactNode;
		/** Narrows the inline padding, for a bar that sits in a narrow column. */
		compact?: boolean;
	};

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const barFrame = {
	display: 'flex',
	flexDirection: 'row',
	alignItems: 'center',
	flexShrink: 1,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'nav',
	justifyContent: 'space-between',
	width: '100%',
	paddingBlock: '8px',
	paddingInline: '16px',
	borderBlockEndStyle: 'solid',
	borderBlockEndColor: 'var(--rcx-color-stroke-light, #cbced1)',
	borderBlockEndWidth: '1px',
	backgroundColor: 'var(--rcx-color-surface-sidebar, #e4e7ea)',
} as const;

const barCompact = {
	paddingInline: '8px',
} as const;

// end of generated

// Declared where they render: zero-runtime only erases a `styled()` whose every use is in its own module
const BarFrame = styled(View, {
	...barFrame,
	variants: {
		compact: { true: barCompact },
	},
});

const NavBar = (props: NavBarProps) => (
	<BarFrame
		compact={props.compact}
		className={prependClassName(props.className, 'rcx-navbar')}
		render={<nav {...ariaAndDataAttributes(props)} {...pickWebPressHandlers(props)} ref={props.ref} id={props.id} title={props.title} />}
	>
		{props.children}
	</BarFrame>
);

export default NavBar;
